/**
 * @name Command Injection
 * @description Detects command injection vulnerabilities in noxfile.py and other scripts.
 * @kind problem
 * @problem.severity error
 * @id py/command-injection-nox
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.Concepts

from DataFlow::CallCfgNode call
where
  (
    // Standard subprocess/os calls
    call = API::moduleImport("subprocess").getMember(["run", "call", "Popen", "check_call", "check_output"]).getACall() or
    call = API::moduleImport("os").getMember(["system", "popen"]).getACall() or
    // Nox session.run calls
    // nox.session.run(...) is a common pattern. 'session' is passed as an argument to the function decorated with @nox.session
    // But efficiently, we can look for calls to .run() on an object that looks like a session.
    // Or simpler: just look for any call to .run() where the first argument might be interesting.
    // For specific library support, we can try to approximate.
    exists(DataFlow::Node func |
        func = call.getFunction() and
        func.asCfgNode().(NameNode).getId() = "run"
    )
  )
select call, "Potential command execution."

/**
 * @name Environment variable injection in noxfile
 * @description Flow from os.environ to nox session.run
 * @kind path-problem
 * @problem.severity warning
 * @id py/nox-env-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module NoxEnvConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source: os.environ lookup or os.getenv
    source = API::moduleImport("os").getMember("environ").getAValueReachableFromSource() or
    source = API::moduleImport("os").getMember("getenv").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: session.run argument
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = "run" and
      sink = call.getArg(_)
    )
  }
}

module NoxEnvFlow = TaintTracking::Global<NoxEnvConfig>;
import NoxEnvFlow::PathGraph

from NoxEnvFlow::PathNode source, NoxEnvFlow::PathNode sink
where NoxEnvFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Environment variable from $@ used in shell command.", source.getNode(), "env var"
